python.code:
class Konto:
    def __init__(self, start):
        self._stand = start     # Konvention: privat

    def einzahlen(self, betrag):
        if betrag > 0:
            self._stand += betrag

    @property
    def stand(self):            # Getter
        return self._stand

k = Konto(100)
k.einzahlen(50)
print(k.stand)   # 150 (lesen via Getter)

cpp.code:
class Konto {
private:
    int stand;
public:
    Konto(int start) : stand(start) {}

    void einzahlen(int betrag) {
        if (betrag > 0) stand += betrag;
    }

    int getStand() const {   // const: ändert nichts
        return stand;
    }
};

Konto k(100);
k.einzahlen(50);
std::cout << k.getStand();   // 150

python.code:
class Tier:
    def __init__(self, name):
        self.name = name
    def gib_laut(self):
        return "..."

class Hund(Tier):
    def __init__(self, name):
        super().__init__(name)
    def gib_laut(self):        # überschreiben
        return "Wuff"

h = Hund("Rex")
print(h.gib_laut())   # Wuff
print(isinstance(h, Tier))   # True

cpp.code:
class Tier {
public:
    Tier(std::string n) : name(n) {}
    virtual std::string gib_laut() { return "..."; }
protected:
    std::string name;
};

class Hund : public Tier {
public:
    Hund(std::string n) : Tier(n) {}
    std::string gib_laut() override { return "Wuff"; }
};

Hund h("Rex");
std::cout << h.gib_laut();   // Wuff
